// Import required modules
const { Uri } = require('vscode');
const { workspace } = require('vscode');

/**
 * Process file links generated by agents.
 *
 * @param {string} filePath - The absolute Windows path of the file link.
 * @returns {Uri} A URI object representing the processed file link.
 */
function processFileLink(filePath) {
  // Check if the file path is an absolute Windows path
  if (filePath.startsWith('c:/')) {
    // Strip drive letters and convert to workspace-relative path
    const relativePath = filePath.replace(/^c:\/(.*$)/, '$1');
    return Uri.file(relativePath);
  } else {
    // The file path is already workspace-relative or a URI scheme
    return Uri.parse(filePath);
  }
}

