import { Uri } from 'vscode';
import { window } from 'vscode';

export class MarkdownLinkHandler {
  private readonly uriSchemeNormalizer: (linkTarget: string) => string;

  constructor() {
    this.uriSchemeNormalizer = this.normalizeUriScheme;
  }

  public resolveLink(linkTarget: string): Uri | null {
    if (!linkTarget || !this.isWindowsDriveLetterPattern(linkTarget)) {
      return null;
    }

    linkTarget = this.uriSchemeNormalizer(linkTarget);

    try {
      const fileUri = Uri.parse(linkTarget);
      return fileUri;
    } catch (error) {
      window.showErrorMessage('Failed to resolve the link');
      return null;
    }
  }

  private isWindowsDriveLetterPattern(linkTarget: string): boolean {
    return /^[a-zA-Z]:[\\/]/.test(linkTarget);
  }

  private normalizeUriScheme(linkTarget: string): string {
    if (!this.isWindowsDriveLetterPattern(linkTarget)) {
      return linkTarget;
    }

    return 'file:///' + linkTarget.replace(/\\/g, '/');
  }
}
