```javascript
// unix_dgram.cc
#include <node.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

using namespace v8;

class UnixDomainDatagramSocket : public node::ObjectWrap {
public:
    static void Initialize(Handle<Object> exports) {
        Local<FunctionTemplate> tpl = FunctionTemplate::New(UnixDomainDatagramSocket::New);
        tpl->SetClassName(String::NewSymbol("UnixDomainDatagramSocket"));
        exports->Set(String::NewSymbol("UnixDomainDatagramSocket"), tpl->GetFunction());
    }

private:
    UnixDomainDatagramSocket() {
        // Initialize the socket
        int sock = socket(AF_UNIX, SOCK_DGRAM, 0);
        if (sock < 0) {
            throw node::Error("Failed to create Unix domain datagram socket");
        }
        this->sock_ = sock;
    }

    static Handle<Function> New(const FunctionCallbackInfo<Value>& args) {
        return Handle<Function>::New(args.Holder()->Get(String::NewSymbol("UnixDomainDatagramSocket")));
    }

public:
    ~UnixDomainDatagramSocket() {
        // Close the socket
        close(this->sock_);
    }

    void bind(const char* path) {
        struct sockaddr_un addr;
        addr.sun_family = AF_UNIX;
        strcpy(addr.sun_path, path);
        unlink(path);  // Remove any existing socket file
        if (bind(this->sock_, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            throw node::Error("Failed to bind Unix domain datagram socket");
        }
    }

    void listen() {
        if (listen(this->sock_, SOMAXCONN) < 0) {
            throw node::Error("Failed to listen on Unix domain datagram socket");
        }
    }

    void send(const char* message, size_t length) {
        struct sockaddr_un addr;
        socklen_t addrlen = sizeof(addr);
        if (getpeername(this->sock_, &addr, &addrlen) < 0) {
            throw node::Error("Failed to get peer name");
        }
        if (sendto(this->sock_, message, length, 0, (struct sockaddr*)&addr, addrlen) < 0) {
            throw node::Error("Failed to send message");
        }
    }

private:
    int sock_;
};

