// Import necessary modules
const vscode = require('vscode');
const path = require('path');

// Define a function to process file links
function processFileLinks(fileLink) {
    // Check if the link is an absolute Windows path
    if (fileLink.startsWith('c:/')) {
        // Convert the absolute path to a workspace-relative path
        const relativePath = path.relative(vscode.workspace.rootPath, fileLink);
        return `[${relativePath}]`;
    } else {
        // The link is already workspace-relative or uses the file:/// URI scheme
        return fileLink;
    }
}

// Define a function to handle agent output
function handleAgentOutput(agentOutput) {
    // Check if the output contains markdown links
    const regex = /\[(.*?)\]\((.*?)\)/g;
    let match;
    while ((match = regex.exec(agentOutput)) !== null) {
        // Process each file link
        const fileLink = processFileLinks(match[2]);
        agentOutput = agentOutput.replace(new RegExp(`\[${match[1]}\]\(${match[2]}\)`, 'g'), `[${match[1]}](${fileLink})`);
    }
    return agentOutput;
}

// Define a function to handle Copilot Chat extension events
function handleCopilotChatExtensionEvents(event) {
    // Check if the event is an agent output event
    if (event.type === 'agentOutput') {
        // Handle the agent output
        const agentOutput = event.data;
        const processedAgentOutput = handleAgentOutput(agentOutput);
        // Send the processed agent output back to the extension
        vscode.postMessage({ type: 'processedAgentOutput', data: processedAgentOutput });
    }
}

// Define a function to initialize the Copilot Chat extension
function initializeCopilotChatExtension() {
    // Listen for Copilot Chat extension events
    vscode.on('copilotChatExtensionEvent', handleCopilotChatExtensionEvents);
}

// Initialize the Copilot Chat extension
initializeCopilotChatExtension();
