 *
 * @param {string} linkTarget - The target URI of the markdown link.
 */
function normalizeWindowsDriveLetters(linkTarget: string): string {
    if (/^[a-zA-Z]:[\\/]/.test(linkTarget)) {
        // Replace Windows drive letters with file:/// scheme
        return Uri.parse('file://' + linkTarget.replace(/\\/g, '/')).toString();
    }
    return linkTarget;
}

