class UnixDgram : public ObjectWrap {
public:
    static void Initialize(Handle<Object> target) {
        Local<FunctionTemplate> template = FunctionTemplate::New(UnixDgram::New);
        target->Set("UnixDgram", template->GetFunction());
    }

private:
    static Handle<Value> New(const Arguments& args) {
        UnixDgram* obj = new UnixDgram();
        obj->Wrap(args.This());
        return args.This();
    }

public:
    UnixDgram() : socket_(socket(AF_UNIX, SOCK_DGRAM, 0)) {}

    ~UnixDgram() {
        ::close(socket_);
    }

    Handle<Value> bind(const char* path) {
        struct sockaddr_un addr;
        addr.sun_family = AF_UNIX;
        strcpy(addr.sun_path, path);
        int result = ::bind(socket_, (struct sockaddr*)&addr, sizeof(addr));
        if (result < 0) {
            return ThrowException(Exception::TypeError("Failed to bind Unix domain datagram socket"));
        }
        return Handle<Value>::New(Null());
    }

    Handle<Value> listen() {
        int result = ::listen(socket_, 1);
        if (result < 0) {
            return ThrowException(Exception::TypeError("Failed to listen on Unix domain datagram socket"));
        }
        return Handle<Value>::New(Null());
    }

    Handle<Value> send(const char* message, size_t length) {
        struct sockaddr_un addr;
        addr.sun_family = AF_UNIX;
        strcpy(addr.sun_path, "/dev/log");
        int result = ::sendto(socket_, message, length, 0, (struct sockaddr*)&addr, sizeof(addr));
        if (result < 0) {
            return ThrowException(Exception::TypeError("Failed to send message over Unix domain datagram socket"));
        }
        return Handle<Value>::New(Null());
    }

private:
    int socket_;
};

