const { createUnixSocket } = require('fs');
const { send, receive } = require('net');

class UnixDgram {
  constructor(path) {
    this.path = path;
    this.socket = createUnixSocket(this.path);
  }

  send(data) {
    return new Promise((resolve, reject) => {
      try {
        const buffer = Buffer.from(data);
        this.socket.send(buffer, (error) => {
          if (error) {
            reject(error);
          } else {
            resolve();
          }
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  receive() {
    return new Promise((resolve, reject) => {
      try {
        const buffer = Buffer.alloc(1024);
        this.socket.recv(buffer, (error) => {
          if (error) {
            reject(error);
          } else {
            resolve(buffer.toString());
          }
        });
      } catch (error) {
        reject(error);
      }
    });
  }

  close() {
    return new Promise((resolve, reject) => {
      try {
        this.socket.close(() => {
          resolve();
        });
      } catch (error) {
        reject(error);
      }
    });
  }
}

